def confus_matrix(data):
    dataR = json.dumps(data.tolist())
    data = data / (data.sum(axis=-1).reshape(-1,1))
    data = data.tolist()
    with open("./liste_relations_tacred.json", "r", encoding="UTF-8") as F:
        dico_relations = json.load(F)
    liste_relations = [x[0] for x in dico_relations["dico_relations"]]

    fig = px.imshow(data,
                    labels=dict(x="Prédiction", y="Réalité", color="Rappel"),
                    x=[XX for XX in liste_relations],
                    y=[XX for XX in liste_relations]
                )
    fig.update_xaxes(tickangle=-90, title_text="Prédictions")
    fig.update_yaxes(title_text="Réalité")
    #fig.show()
    with wandb.init(project="EXPE_20_Nov_2025_10H01_25787521", name="confus_test_set") as run:
        monplot = wandb.Plotly(fig)
        run.log({"confusion_matrix": monplot, "confus": dataR})
        run.finish()
    print("TERMINÉ.")




if __name__ == "__main__":
    #wandb.login()
    confus_matrix(confusion_test)